mapper.select:
UPDATE batch.console_ai_conversation
   SET next_turn_no = next_turn_no + 1,
       updated_at = CURRENT_TIMESTAMP,
       expires_at = #{expiresAt},
       context_version = #{contextVersion}
 WHERE id = #{conversationId}
   AND owner_user_id = #{ownerUserId}
RETURNING next_turn_no - 1

SELECT id, tenant_id, owner_user_id, title, context_version, next_turn_no, created_at, updated_at, expires_at
  FROM batch.console_ai_conversation
 WHERE owner_user_id = #{ownerUserId}
 ORDER BY updated_at DESC, id DESC
 LIMIT #{limit}

SELECT t.id, t.tenant_id, t.conversation_id, t.turn_no, t.context_version, t.prompt_text,
       t.response_text, t.turn_status, t.prompt_decision, t.model_name, t.prompt_tokens,
       t.completion_tokens, t.estimated_cost_usd, t.created_at, t.completed_at
  FROM batch.console_ai_turn t
  JOIN batch.console_ai_conversation c
    ON c.tenant_id = t.tenant_id AND c.id = t.conversation_id
 WHERE c.id = #{conversationId}
   AND c.owner_user_id = #{ownerUserId}

   AND t.turn_no < #{beforeTurnNo}

 ORDER BY t.turn_no DESC
 LIMIT #{limit}

mapper.delete:
DELETE FROM batch.console_ai_conversation
 WHERE id = #{conversationId}
   AND owner_user_id = #{ownerUserId}
